public static int calculateTimeNeeded(int N) {
    if (N == 0) {
        return 0;
    }
    int timeNeeded = 0;
    int[] seats = new int[N];
    for (int i = 0; i < N; i++) {
        seats[i] = i + 1;
    }
    int swapCount = 0;
    while (swapCount < N - 1) {
        for (int i = 0; i < N - 1; i++) {
            if (seats[i] > seats[i + 1]) {
                timeNeeded += seats[i + 1] / seats[i];
                swapCount++;
                seats[i] = seats[i + 1];
